/* Letter module dataset — generated. Letters carry the FULL source content
   from lettters/, corrected for errors, with additions merged alongside. */
const LETTERDATA = [{"group":"The Format","topics":[{"id":"pourquoi","kind":"lesson","en":{"title":"Why this question?","paras":["In the exam, question 2 is always the same: write ONE letter of about 80 words. You choose one topic out of three. This question is worth 10 marks, every year, without exception.","The topic changes, but the structure never does. The place, the date, the greeting, the paragraphs, the closing phrase and the signature are always the same.","So you can prepare this question completely. Learn the skeleton and the set phrases by heart: about thirty of your eighty words are already written before you even see the topic."]},"fr":{"title":"Pourquoi cette question","paras":["À l'examen, la question 2 est toujours la même : écrivez UNE lettre d'environ 80 mots. Vous choisissez un sujet parmi trois. Cette question vaut 10 points, chaque année, sans exception.","Le sujet change, mais la structure ne change jamais. Le lieu, la date, l'appel, les paragraphes, la formule de clôture et la signature sont toujours identiques.","Vous pouvez donc préparer cette question complètement. Apprenez le squelette et les formules par cœur : environ trente mots sur quatre-vingts sont déjà écrits avant même de voir le sujet."]},"box":{"tone":"tip","fr":"L'examinateur coche une liste : le format, le registre (tu), le contenu, la grammaire, environ 80 mots.","en":"The examiner ticks a list: format, tone (using tu), content, grammar, about 80 words."}},{"id":"squelette","kind":"lesson","en":{"title":"The Structure","paras":["A friendly letter always has the same parts, in the same order, in the same places on the page.","Top right: the place and the date. On the left, below it: the greeting, followed by a comma. Then the body of the letter, in two or three paragraphs.","At the end: a closing sentence, then the sign-off phrase and your signature, both on the right.","Draw this frame before you write. Two minutes is enough, and it protects the marks that do not depend on your French at all."]},"fr":{"title":"Le squelette","paras":["Une lettre amicale a toujours les mêmes zones, dans le même ordre, aux mêmes endroits sur la page.","En haut à droite : le lieu et la date. À gauche, en dessous : l'appel, suivi d'une virgule. Ensuite le corps de la lettre, en deux ou trois paragraphes.","À la fin : une phrase de clôture, puis la formule de politesse et la signature, toutes les deux à droite.","Dessinez ce cadre avant d'écrire. Deux minutes suffisent, et vous protégez les points qui ne dépendent pas du tout de votre français."]},"box":{"tone":"rule","fr":"Sept zones : ① lieu et date ② l'appel ③ l'introduction ④ le corps ⑤ la conclusion ⑥ la formule de politesse ⑦ la signature.","en":"Seven parts: 1 place and date, 2 the greeting, 3 the opening, 4 the body, 5 the closing sentence, 6 the sign-off, 7 your signature."},"blueprint":true},{"id":"lieu-date","kind":"lesson","en":{"title":"Place and Date","paras":["The place-and-date line goes in the top right corner. The format is always: the town, a comma, then \"le\", the day as a number, the month, the year.","For example: Koweït, le 13 octobre 2024. Or: Nice, le 24 octobre 2026.","Three traps live in this line. Months never take a capital letter in French. The day is a plain number, not an ordinal. And the comma after the town is required.","There is one exception: the first day of the month is written \"1er\". For example, le 1er mai 2026."]},"fr":{"title":"Lieu et date","paras":["La ligne du lieu et de la date se place en haut à droite. Le format est toujours : la ville, une virgule, puis « le », le jour en chiffre, le mois, l'année.","Par exemple : Koweït, le 13 octobre 2024. Ou encore : Nice, le 24 octobre 2026.","Trois pièges vivent dans cette ligne. Le mois ne prend jamais de majuscule en français. Le jour est un chiffre ordinaire, pas un ordinal. Et la virgule après la ville est obligatoire.","Une seule exception : le premier jour du mois s'écrit « 1er ». Par exemple, le 1er mai 2026."]},"compare":{"fr":"Correct / Incorrect","en":"Correct / Incorrect","rows":[{"aspect":{"fr":"Le mois","en":"The month"},"good":"le 14 juillet 2026","bad":"le 14 Juillet 2026","why":{"fr":"Les mois ne prennent jamais de majuscule.","en":"Months never take a capital letter."}},{"aspect":{"fr":"L'article","en":"The article"},"good":"Paris, le 5 mai 2026","bad":"Paris, 5 mai 2026","why":{"fr":"« le » est obligatoire.","en":"The word \"le\" is required."}},{"aspect":{"fr":"La virgule","en":"The comma"},"good":"Nice, le 24 octobre","bad":"Nice le 24 octobre","why":{"fr":"Une virgule sépare toujours la ville de la date.","en":"A comma always separates the town from the date."}},{"aspect":{"fr":"Le premier","en":"The first"},"good":"le 1er mai 2026","bad":"le 1 mai 2026","why":{"fr":"Seul le premier du mois prend « er ».","en":"Only the 1st of the month takes \"er\"."}}]}},{"id":"appel-signature","kind":"lesson","en":{"title":"Salutation and Signature","paras":["The greeting goes on the left and always ends with a comma. Use \"Cher\" before a boy's name and \"Chère\" before a girl's name.","For several people: \"Chers amis,\" if the group is male or mixed, \"Chères amies,\" if the group is all female. For family: \"Chère maman,\", \"Cher papa,\", \"Chers parents,\".","The signature goes on the right, on two lines: first the sign-off phrase with a comma, then your first name underneath.","Strict rule: first name only. Never a surname, never a title. \"Marc Dupont\" or \"M. Dupont\" turns a friendly letter into a formal one and loses you marks."]},"fr":{"title":"Appel et signature","paras":["L'appel se place à gauche et se termine toujours par une virgule. On écrit « Cher » devant un prénom masculin et « Chère » devant un prénom féminin.","Pour plusieurs personnes : « Chers amis, » si le groupe est masculin ou mixte, « Chères amies, » si le groupe est entièrement féminin. Pour la famille : « Chère maman, », « Cher papa, », « Chers parents, ».","La signature se place à droite, sur deux lignes : d'abord la formule de politesse avec une virgule, puis votre prénom en dessous.","Règle stricte : le prénom seul. Jamais de nom de famille, jamais de titre. « Marc Dupont » ou « M. Dupont » transforme la lettre amicale en lettre formelle et coûte des points."]},"box":{"tone":"warn","fr":"Accordez la signature au lecteur : « Ton ami(e), » à un ami, « Ton fils / Ta fille, » à un parent, « Ton cousin / Ta cousine, » à un cousin.","en":"Match the sign-off to your reader: \"Ton ami(e),\" to a friend, \"Ton fils / Ta fille,\" to a parent, \"Ton cousin / Ta cousine,\" to a cousin."}},{"id":"budget","kind":"lesson","en":{"title":"The 80-Word Limit","paras":["Aim for 80 words. Between 75 and 90 you are in the right range. Much longer, and mistakes pile up without earning a single extra mark.","The first paragraph is about 15 words: the greeting and saying what the letter is about. These sentences are memorised, so they cost you no thinking time.","The body is about 50 words: four to six sentences from your phrase bank. This is the only part that changes with the topic.","The ending is about 15 words: a closing sentence and the signature. Memorised as well."]},"fr":{"title":"Le budget de 80 mots","paras":["Visez 80 mots. Entre 75 et 90, vous êtes dans la bonne zone. Beaucoup plus long, et les fautes s'accumulent sans rapporter un seul point de plus.","Le premier paragraphe fait environ 15 mots : la salutation et l'annonce du sujet. Ces phrases sont apprises par cœur, donc elles ne coûtent aucun temps de réflexion.","Le corps fait environ 50 mots : quatre à six phrases tirées de votre banque de phrases. C'est la seule partie qui change selon le sujet.","La fin fait environ 15 mots : une phrase de clôture et la signature. Apprises par cœur elles aussi."]},"box":{"tone":"tip","fr":"Trente de vos quatre-vingts mots sont déjà écrits avant l'examen. Il ne vous reste qu'un problème de cinquante mots.","en":"Thirty of your eighty words are written before the exam even starts. That leaves you a fifty-word problem."}},{"id":"entrainement","kind":"lesson","en":{"title":"Practice — The Format","paras":["Fix the format mistakes. Each question is only about structure, never about content."]},"fr":{"title":"Entraînement — le format","paras":["Corrigez les fautes de format. Chaque question ne porte que sur la structure, jamais sur le contenu."]},"quiz":[{"q":{"fr":"Quelle ligne de date est correcte ?","en":"Which date line is correct?"},"options":["le 13 Octobre 2024","le 13 octobre 2024","le 13e octobre 2024"],"answer":1,"why":{"fr":"Chiffre ordinaire, mois en minuscule, pas de terminaison ordinale.","en":"Plain number, lowercase month, no ordinal ending."}},{"q":{"fr":"Vous écrivez à votre mère. Quel appel ?","en":"You are writing to your mother. Which greeting?"},"options":["Cher maman,","Chère maman,","Chère Maman"],"answer":1,"why":{"fr":"« maman » est féminin, et la ligne se termine par une virgule.","en":"\"maman\" is feminine, and the line ends with a comma."}},{"q":{"fr":"Même lettre à votre mère. Comment signez-vous ?","en":"Same letter to your mother. How do you sign off?"},"options":["Ton ami,","Ton fils,","Monsieur,"],"answer":1,"why":{"fr":"La signature indique votre lien avec le lecteur.","en":"The signature states your relationship to the reader."}},{"q":{"fr":"Le premier mai. Quelle forme ?","en":"The first of May. Which form?"},"options":["le 1 mai 2025","le 1er mai 2025","le premier Mai 2025"],"answer":1,"why":{"fr":"Le premier du mois est la seule exception ordinale.","en":"The 1st of the month is the only ordinal exception."}}]}]},{"group":"Useful Phrases","topics":[{"id":"ouvrir","kind":"lesson","en":{"title":"Opening the letter","paras":["Learn three openings and you will never need a fourth.","The safest one, which works for any topic: \"Comment vas-tu ? J'espère que cette lettre te trouvera en bonne santé.\" — How are you? I hope this letter finds you in good health.","Shorter and very natural: \"Comment ça va ? Moi, je vais bien ici.\" — How are things? I'm well here.","And when the question says your friend wrote to you: \"J'ai reçu ta lettre dans laquelle tu m'as demandé des informations sur…\" — I got your letter in which you asked me about…"]},"fr":{"title":"Ouvrir la lettre","paras":["Apprenez trois ouvertures et vous n'en aurez jamais besoin d'une quatrième.","La plus sûre, qui convient à n'importe quel sujet : « Comment vas-tu ? J'espère que cette lettre te trouvera en bonne santé. »","Plus courte et très naturelle : « Comment ça va ? Moi, je vais bien ici. »","Et quand le sujet dit que votre ami vous a écrit : « J'ai reçu ta lettre dans laquelle tu m'as demandé des informations sur… »"]},"box":{"tone":"tip","fr":"« dans laquelle » est un pronom relatif composé — la même grammaire que la Section C. Une phrase apprise, des points dans deux sections.","en":"\"dans laquelle\" is a compound relative pronoun — the same grammar as Section C. One memorised sentence earns marks in two places."}},{"id":"annoncer","kind":"lesson","en":{"title":"Saying what it is about","paras":["One sentence between the greeting and the content. It proves to the examiner that you understood the question.","\"Je t'écris cette lettre pour parler de l'environnement.\" — I'm writing to talk about the environment. Change the last few words and the same sentence covers all eight topics.","Other versions: \"Dans cette lettre, je voudrais t'écrire au sujet de…\" — In this letter I'd like to write to you about… or \"Aujourd'hui, je veux partager avec toi…\" — Today I want to share with you…"]},"fr":{"title":"Annoncer le sujet","paras":["Une phrase entre la salutation et le contenu. Elle prouve à l'examinateur que vous avez compris le sujet.","« Je t'écris cette lettre pour parler de l'environnement. » Changez les derniers mots et la même phrase sert pour les huit thèmes.","Autres versions : « Dans cette lettre, je voudrais t'écrire au sujet de… » ou « Aujourd'hui, je veux partager avec toi… »"]}},{"id":"charnieres","kind":"lesson","en":{"title":"Linking words","paras":["Without them, the body of your letter is a list of unconnected sentences. With them it becomes a paragraph that holds together — and that is exactly what earns the content marks.","Six are enough: d'abord (first of all), ensuite (then), de plus (furthermore), cependant (however), parce que (because), enfin (finally).","In practice: \"First of all, you need to rest. Then, eat fresh fruit. Furthermore, drink lots of water. However, avoid fast food. Finally, do a little sport because it helps you recover.\""]},"fr":{"title":"Les mots charnières","paras":["Sans eux, le corps de la lettre est une liste de phrases sans lien. Avec eux, c'est un paragraphe qui se tient — et c'est exactement ce que cherche l'examinateur.","Six suffisent : d'abord, ensuite, de plus, cependant, parce que, enfin.","En pratique : « D'abord, il faut que tu te reposes. Ensuite, mange des fruits frais. De plus, bois beaucoup d'eau. Cependant, évite le fast-food. Enfin, fais un peu de sport parce que cela aide à récupérer. »"]},"box":{"tone":"rule","fr":"Cinq phrases, cinq connecteurs — et vous avez les cinquante mots dont le corps a besoin.","en":"Five sentences, five linking words — and you have the fifty words the body needs."}},{"id":"clore","kind":"lesson","en":{"title":"Ending the letter","paras":["Two short lines, then stop.","Ask for a reply: \"Écris-moi vite.\" (Write soon) · \"Réponds-moi.\" (Reply to me) · \"J'attends ta réponse avec impatience.\" (I'm looking forward to your reply)","Send greetings: \"Dis bonjour à tes parents de ma part.\" (Say hello to your parents from me) · \"Donne mes salutations à tout le monde.\" (Give my regards to everyone)","A closing that matches the topic is worth more than a generic one: \"Bonne chance !\" after advice about work, \"Soigne-toi bien !\" after advice about health."]},"fr":{"title":"Clore la lettre","paras":["Deux courtes lignes, puis on s'arrête.","Demandez une réponse : « Écris-moi vite. » · « Réponds-moi. » · « J'attends ta réponse avec impatience. »","Envoyez des salutations : « Dis bonjour à tes parents de ma part. » · « Donne mes salutations à tout le monde. »","Une clôture liée au thème vaut mieux qu'une clôture passe-partout : « Bonne chance ! » après des conseils sur le travail, « Soigne-toi bien ! » après des conseils sur la santé."]}},{"id":"signer","kind":"lesson","en":{"title":"Signing off","paras":["The sign-off phrase always ends with a comma, and your first name alone goes underneath it.","Neutral and always safe: Ton ami, / Ton amie, — Your friend,","Warmer: Amitiés, · Amicalement, · Bises, · Affectueusement, · À bientôt, — the last one means \"see you soon\". \"Bises\" means kisses, so keep it for close friends and family.","For family: Ton fils, (your son) · Ta fille, (your daughter) · Ton cousin, · Ta cousine,"]},"fr":{"title":"Signer","paras":["La formule de politesse se termine toujours par une virgule, et votre prénom seul se place en dessous.","Neutre et toujours sûr : Ton ami, / Ton amie,","Plus chaleureux : Amitiés, · Amicalement, · Bises, · Affectueusement, · À bientôt,","En famille : Ton fils, · Ta fille, · Ton cousin, · Ta cousine,"]},"box":{"tone":"warn","fr":"N'utilisez jamais Cordialement, Sincèrement ou Veuillez agréer. Ce sont des formules de lettre formelle : elles coûtent le point de registre.","en":"Never use Cordialement, Sincèrement or Veuillez agréer. These belong to formal letters and will cost you the register mark."}}]},{"group":"The Tone (Register)","topics":[{"id":"tu-jamais-vous","kind":"lesson","en":{"title":"Use tu, never vous","paras":["Every Section B letter is written to a friend, a cousin, a parent or a pen-friend your own age. That means using \"tu\" from the first word to the last.","\"Comment vas-tu ? Ton travail te plaît ? Écris-moi.\" — correct.","\"Comment allez-vous ? Votre travail vous plaît ?\" — correct French, wrong letter. This loses you the register mark.","There is one exception: if the letter is addressed to two people, for example \"Chers papa et maman,\", then \"vous\" is the plural form and it is right."]},"fr":{"title":"Tu, jamais vous","paras":["Toutes les lettres de la Section B s'adressent à un ami, un cousin, un parent ou un correspondant de votre âge. Cela veut dire « tu » du premier mot au dernier.","« Comment vas-tu ? Ton travail te plaît ? Écris-moi. » — correct.","« Comment allez-vous ? Votre travail vous plaît ? » — français correct, mauvaise lettre. Cela coûte le point de registre.","Une seule exception : si la lettre s'adresse à deux personnes, par exemple « Chers papa et maman, », alors « vous » est le pluriel et il est juste."]}},{"id":"ce-que-tu-change","kind":"lesson","en":{"title":"What \"tu\" changes","paras":["Choosing \"tu\" changes four things at once, and you have to change all of them.","The verb: vous allez → tu vas; vous êtes → tu es.","The possessive: votre lettre → ta lettre; vos parents → tes parents.","The object pronoun: je vous écris → je t'écris. And the imperative: écrivez-moi → écris-moi; répondez-moi → réponds-moi."]},"fr":{"title":"Ce que « tu » change","paras":["Choisir « tu » change quatre choses à la fois, et il faut les changer toutes.","Le verbe : vous allez → tu vas ; vous êtes → tu es.","Le possessif : votre lettre → ta lettre ; vos parents → tes parents.","Le pronom objet : je vous écris → je t'écris. Et l'impératif : écrivez-moi → écris-moi ; répondez-moi → réponds-moi."]},"box":{"tone":"tip","fr":"Ces quatre points viennent tous de la Section C — possessifs, pronoms personnels, impératif. La lettre est l'endroit où vous prouvez que vous savez les employer.","en":"All four of these come from Section C — possessives, object pronouns, the imperative. The letter is where you show you can actually use them."}},{"id":"fautes","kind":"lesson","en":{"title":"Mistakes that cost marks","paras":["Six mistakes come up every year.","Mixing \"tu\" and \"vous\" — by far the most common. Putting a capital on the month: \"le 13 Octobre\" instead of \"le 13 octobre\". Forgetting the town before the date.","Writing \"Cher\" before a girl's name. Signing \"Cordialement\" in a friendly letter. And the most expensive of all: writing about the wrong thing.","The register mistake rarely happens at the start. You begin with \"tu\", drift into \"vous\" in the second paragraph, and never notice. Check every verb before you hand in."]},"fr":{"title":"Les fautes qui coûtent","paras":["Six fautes reviennent chaque année dans les copies.","Mélanger « tu » et « vous » — de loin la plus fréquente. Mettre une majuscule au mois : « le 13 Octobre » au lieu de « le 13 octobre ». Oublier la ville avant la date.","Écrire « Cher » devant un prénom féminin. Signer « Cordialement » dans une lettre amicale. Et la plus chère de toutes : répondre à côté du sujet.","La faute de registre arrive rarement au début. On commence avec « tu », on glisse vers « vous » au deuxième paragraphe, et on ne le remarque jamais. Relisez chaque verbe avant de rendre."]}},{"id":"ton-juste","kind":"lesson","en":{"title":"Getting the tone right","paras":["Several topics ask you to give advice: about health, unemployment, the environment. French gives you three levels.","Direct — the imperative: \"Sois optimiste !\" (Be optimistic!) \"Ne t'inquiète pas !\" (Don't worry!) This sounds warm between friends.","Softer — devoir or pouvoir: \"Tu dois te reposer.\" (You must rest.) \"Tu peux faire du sport.\" (You can do sport.)","Strongest — the subjunctive: \"Il faut que tu te reposes.\" (You really need to rest.) Use all three in one letter: that variety is the difference between a good answer and a very good one."]},"fr":{"title":"Le ton juste","paras":["Plusieurs sujets demandent de donner un conseil : sur la santé, le chômage, l'environnement. Le français vous offre trois niveaux.","Direct — l'impératif : « Sois optimiste ! » « Ne t'inquiète pas ! » C'est chaleureux entre amis.","Plus doux — devoir ou pouvoir : « Tu dois te reposer. » « Tu peux faire du sport. »","Le plus fort — le subjonctif : « Il faut que tu te reposes. » Employez les trois dans une même lettre : c'est cette variété qui fait la différence entre une bonne copie et une très bonne copie."]},"box":{"tone":"rule","fr":"Piège : « Ne t'inquiète pas ! » — à l'impératif négatif, le pronom passe devant le verbe. « Ne inquiète-toi pas » est faux.","en":"Trap: \"Ne t'inquiète pas !\" — in a negative imperative the pronoun goes in front of the verb. \"Ne inquiète-toi pas\" is wrong."}}]},{"group":"Model Letters","topics":[{"id":"let-edu-fr","kind":"letter","lecon":"Ch 2","fr":{"title":"Le système éducatif en France"},"en":{"title":"The French Education System"},"prompt":{"fr":"Vous êtes en France, décrivez le système éducatif de la France à votre amie.","en":"You are in France, describe the French education system to your friend."},"years":["CBSE 2024","CBSE 2020"],"letter":{"fr":{"date":"Paris, le 22 mai 2021","salutation":"Chère Marie,","paras":["Comment vas-tu ? Je vais bien ici et mes études ont déjà commencé.","Dans cette lettre, je vais te décrire l'enseignement français. L'enseignement en France est un peu différent de celui en Inde. Il est aussi gratuit, public et obligatoire jusqu'à 16 ans. L'enseignement est divisé en trois degrés : primaire, secondaire et supérieur.","Au degré primaire, l'enfant peut commencer sa scolarité à l'âge de 2 ans à 6 ans avec l'école maternelle. Ensuite, l'école primaire à l'âge de 6 ans à 10 ans. À l'enseignement secondaire, l'enfant entre au collège de 11 ans à 15 ans et puis au lycée à l'âge de 15 ans à 18 ans.","Au lycée, les trois années s'appellent la Seconde, la Première et la Terminale.","On obtient le diplôme du Brevet pour le collège et le Baccalauréat pour le lycée. À la fin, l'enseignement supérieur est l'université. Après le Bac, on peut choisir la formation professionnelle.","Et toi, quel est le système en Inde ? J'attends ta réponse."],"closing":["Ton amie,"],"signature":"Caroline"},"en":{"date":"Paris, 22 May 2021","salutation":"Dear Marie,","paras":["How are you? I am doing well here and my studies have already started.","In this letter I will describe French education to you. Teaching in France is a little different from teaching in India. It is also free, public and compulsory up to 16 years old. Education is divided into three levels: primary, secondary and higher.","At primary level, a child can start school between the ages of 2 and 6 with nursery school. Then comes primary school, from 6 to 10 years old. In secondary education, the child goes to middle school from 11 to 15, and then to high school from 15 to 18.","At high school, the three years are called Seconde, Première and Terminale.","You get the Brevet diploma for middle school and the Baccalaureate for high school. Finally, higher education is university. After the Bac, you can choose vocational training.","And you, what is the system like in India? I am waiting for your reply."],"closing":["Your friend,"],"signature":"Caroline"}},"vocab":[["l'école maternelle (2 à 6 ans)","nursery school"],["l'école primaire (6 à 10 ans)","primary school"],["le collège (11 à 15 ans) → le Brevet","middle school → the Brevet"],["le lycée (15 à 18 ans) → le Baccalauréat","high school → the Bac"],["gratuit, public et obligatoire","free, public and compulsory"],["les trois degrés : primaire, secondaire, supérieur","the three levels"],["l'enseignement supérieur : l'université","higher education: university"],["la formation professionnelle","vocational training"]],"bank":[["L'enseignement est gratuit, public et obligatoire jusqu'à 16 ans.","Education is free, public and compulsory up to 16."],["L'enseignement est divisé en trois degrés.","Education is divided into three levels."],["L'enseignement en France est un peu différent de celui en Inde.","Education in France is a little different from India."],["Après le Bac, on peut choisir la formation professionnelle.","After the Bac you can choose vocational training."]],"notes":["Corrections apportées au français d'origine : « système d'éducatif » → « système éducatif » ; « commencer son scolaire » → « commencer sa scolarité » ; « J'attends pour ta réponse » → « J'attends ta réponse » ; virgule ajoutée après la formule de politesse.","Ajouts : la phrase sur la Seconde, la Première et la Terminale, et la question finale « Et toi, quel est le système en Inde ? » ne sont pas dans la lettre d'origine."]},{"id":"let-edu-in","kind":"letter","lecon":"Ch 2","fr":{"title":"Le système éducatif en Inde"},"en":{"title":"The Indian Education System"},"prompt":{"fr":"Vous êtes en Inde. Décrivez le système éducatif de l'Inde à votre amie.","en":"You are in India, describe the Indian education system to your friend."},"years":[],"letter":{"fr":{"date":"Delhi, le 29 juin 2023","salutation":"Chère Marie,","paras":["Comment ça va ? Je vais bien et mes études vont bien commencer.","Dans cette lettre, je vais te décrire l'enseignement indien. L'enseignement en Inde est gratuit, public et obligatoire jusqu'à 14 ans. Il est divisé en trois degrés : primaire, secondaire et supérieur.","Au degré primaire, l'enfant peut commencer sa scolarité à l'âge de 2 ans à 6 ans avec l'école maternelle. Ensuite, l'école primaire à l'âge de 6 ans à 10 ans.","À l'école secondaire, l'enfant entre en « high school » à l'âge de 11 ans à 15 ans. Après avoir passé l'examen du Certificat de l'école secondaire (CBSE), l'enfant entre en « higher secondary school » (11th & 12th class) à l'âge de 15 ans à 17 ans. Enfin, après l'enseignement « higher secondary », on va à l'université.","Le système suit le modèle 10 + 2 + 3.","Explique-moi le système éducatif en France. J'attends ta lettre."],"closing":["Ton amie,"],"signature":"Tanya"},"en":{"date":"Delhi, 29 June 2023","salutation":"Dear Marie,","paras":["How are you? I am doing well and my studies are about to start.","In this letter I will describe Indian education to you. Education in India is free, public and compulsory up to the age of 14. It is divided into three levels: primary, secondary and higher.","At primary level, a child can start school between the ages of 2 and 6 with nursery school. Then comes primary school, from 6 to 10 years old.","In secondary education, the child enters high school between the ages of 11 and 15. After passing the Central Board of Secondary Education (CBSE) exam, the child goes into higher secondary school (11th and 12th class) between 15 and 17. Finally, after higher secondary, you go to university.","The system follows the 10 + 2 + 3 model.","Explain the French education system to me. I am waiting for your letter."],"closing":["Your friend,"],"signature":"Tanya"}},"vocab":[["gratuit, public et obligatoire jusqu'à 14 ans","free, public and compulsory up to 14"],["l'école maternelle (2 à 6 ans)","nursery school"],["l'école primaire (6 à 10 ans)","primary school"],["« high school » (11 à 15 ans)","high school"],["le Certificat de l'école secondaire (CBSE)","the CBSE certificate"],["« higher secondary school » (11th & 12th class)","higher secondary, 15 to 17"],["le modèle 10 + 2 + 3","the 10+2+3 model"]],"bank":[["L'enseignement en Inde est gratuit, public et obligatoire jusqu'à 14 ans.","Education in India is free, public and compulsory up to 14."],["Il est divisé en trois degrés : primaire, secondaire et supérieur.","It is divided into three levels."],["Après avoir passé l'examen du CBSE, l'enfant entre en « higher secondary school ».","After passing the CBSE exam the child goes into higher secondary."]],"notes":["Corrections : « Comment ça-va ? » → « Comment ça va ? » ; « je vais te décrire de l'enseignement » → sans « de » ; « commencer sont scolaires » → « commencer sa scolarité » ; « J'attends pour ta lettre » → « J'attends ta lettre ».","Ajout : « Le système suit le modèle 10 + 2 + 3 » n'est pas dans la lettre d'origine."]},{"id":"let-chomage","kind":"letter","lecon":"Ch 3","fr":{"title":"Conseils à un ami au chômage"},"en":{"title":"Advice to an Unemployed Friend"},"prompt":{"fr":"Écrivez une lettre d'environ 80 mots à votre ami qui est au chômage. Donnez-lui des conseils.","en":"Write a letter of about 80 words to your friend who is unemployed. Give him advice."},"years":["CBSE 2023"],"letter":{"fr":{"date":"Rouen, le 19 juillet 2026","salutation":"Cher Paul,","paras":["Comment vas-tu ? J'ai reçu ta lettre dans laquelle tu as écrit que tu es au chômage depuis un an. Ne t'inquiète pas !","Tu peux faire de l'intérim de temps en temps. Tu dois t'inscrire sur le site internet de pôle-emploi.fr. Est-ce que tu parcours les petites annonces ? Si non, il faut que tu le fasses.","Je sais que tu as un bon CV. Alors, tu ne dois pas avoir de problèmes. Sois optimiste ! Bientôt tu trouveras un bon métier dont tu seras fier.","Bonne chance !"],"closing":["Ton ami,"],"signature":"Rahul"},"en":{"date":"Rouen, 19 July 2026","salutation":"Dear Paul,","paras":["How are you? I received your letter in which you wrote that you have been unemployed for a year. Don't worry!","You can do temporary work from time to time. You must register on the pôle-emploi.fr website. Do you look through the small ads? If not, you need to start.","I know you have a good CV. So you shouldn't have any problems. Be optimistic! Soon you will find a good job that you will be proud of.","Good luck!"],"closing":["Your friend,"],"signature":"Rahul"}},"vocab":[["être au chômage","to be unemployed"],["faire de l'intérim","to do temporary work"],["le site internet de pôle-emploi.fr","the pôle-emploi.fr website"],["les petites annonces","the small ads"],["un CV","a CV / résumé"],["un métier dont tu seras fier","a job you will be proud of"]],"bank":[["Ne t'inquiète pas !","Don't worry!"],["Tu dois t'inscrire sur le site internet de pôle-emploi.fr.","You must register on pôle-emploi.fr."],["Il faut que tu le fasses.","You need to do it."],["Sois optimiste !","Be optimistic!"],["Bientôt tu trouveras un bon métier dont tu seras fier.","Soon you'll find a good job you'll be proud of."]],"notes":["Cette lettre est la seule du dossier qui n'a rien perdu : tout le contenu d'origine est présent.","Corrections : « les annonces classées » → « les petites annonces » ; « il faut que tu le commences » → « que tu le fasses » ; « Bonne Chance » → « Bonne chance » ; année ajoutée à la date ; virgules ajoutées.","Grammaire à montrer : « dans laquelle » et « dont » (relatifs), « il faut que » + subjonctif, « Sois » (impératif irrégulier), « tu trouveras » (futur simple)."]},{"id":"let-nouveau-job","kind":"letter","lecon":"Ch 3","fr":{"title":"Décrire son nouveau travail"},"en":{"title":"Describing Your New Job"},"prompt":{"fr":"Vous travaillez à l'étranger. Vous écrivez une lettre à votre père en lui décrivant votre travail, votre bureau et combien cela vous plaît.","en":"You work abroad. Write a letter to your father describing your work, your office and how much you like it."},"years":["CBSE 2020"],"letter":{"fr":{"date":"Paris, le 22 juillet 2021","salutation":"Cher Papa,","paras":["Comment ça va ? Je vais bien ici à Paris. Dans cette lettre, je vais parler de ma profession.","Tu seras content d'apprendre que j'ai trouvé un très bon emploi.","Je travaille comme informaticien à HCL. C'est un travail dont je suis fier. J'ai beaucoup de travail à faire. Il y a 50 personnes dans mon entreprise.","Il n'y a ni d'heures fixées ni de congés. Quelquefois, je travaille tout le jour et toute la nuit. C'est un travail dur mais cela me plaît. C'est aussi une profession bien payée.","Cependant, les horaires sont longs : je travaille souvent dix heures par jour.","Mon patron et mes collègues sont bons et géniaux.","Mon bureau est un peu petit mais il y a toutes les choses dont j'ai besoin comme l'ordinateur, l'imprimante, le scanner, la webcam, le graveur de CD, le modem, etc.","Dès que j'aurai eu congé, je viendrai.","Donne mes salutations et mon amour à maman et à Monica. Tu me manques."],"closing":["Ton fils,"],"signature":"Ross"},"en":{"date":"Paris, 22 July 2021","salutation":"Dear Dad,","paras":["How are you? I am doing well here in Paris. In this letter I am going to talk about my job.","You will be happy to hear that I have found a very good job.","I work as an IT professional at HCL. It is work I am proud of. I have a lot of work to do. There are 50 people in my company.","There are no set hours and no holidays. Sometimes I work all day and all night. It is hard work but I enjoy it. It is also a well-paid profession.","However, the hours are long: I often work ten hours a day.","My boss and my colleagues are good and great.","My office is a bit small but it has everything I need — the computer, the printer, the scanner, the webcam, the CD burner, the modem, and so on.","As soon as I get time off, I will come.","Give my regards and my love to Mum and to Monica. I miss you."],"closing":["Your son,"],"signature":"Ross"}},"vocab":[["un informaticien","an IT professional"],["HCL","the company he works for"],["une profession bien payée","a well-paid profession"],["mon patron","my boss"],["l'ordinateur, l'imprimante, le scanner","computer, printer, scanner"],["la webcam, le graveur de CD, le modem","webcam, CD burner, modem"],["les congés","time off, holidays"]],"bank":[["C'est un travail dont je suis fier.","It is work I am proud of."],["C'est un travail dur mais cela me plaît.","It is hard work but I enjoy it."],["C'est aussi une profession bien payée.","It is also a well-paid profession."],["Mon patron et mes collègues sont bons et géniaux.","My boss and colleagues are good and great."],["Dès que j'aurai eu congé, je viendrai.","As soon as I get time off, I will come."]],"notes":["ATTENTION — cette lettre contient deux versions qui se contredisent, conservées volontairement : la lettre d'origine dit « Il n'y a ni d'heures fixées ni de congés », l'ajout dit « je travaille souvent dix heures par jour » et « Dès que j'aurai eu congé ». Choisissez l'une des deux quand vous rédigez.","Corrections : année à deux chiffres (« 21 ») complétée en « 2021 » ; « cela me plait » → « plaît » ; ligne « Ton fils, » ajoutée, absente de l'original.","Grammaire à montrer : « dont » (relatif), « dès que j'aurai eu » (futur antérieur)."]},{"id":"let-sorbonne","kind":"letter","lecon":"Ch 3","fr":{"title":"La vie et les études à la Sorbonne"},"en":{"title":"Life and Studies at the Sorbonne"},"prompt":{"fr":"Vous êtes à l'université de la Sorbonne. Décrivez votre vie, vos études.","en":"You are at the University of the Sorbonne. Describe your life and your studies."},"years":[],"letter":{"fr":{"date":"Paris, le 5 juillet 2025","salutation":"Cher Papa,","paras":["Comment vas-tu ? Je suis bien installé à Paris et je voulais te donner de mes nouvelles.","Je suis à l'université de la Sorbonne. C'est la plus ancienne université de Paris, créée par Robert de Sorbonne en 1257. C'est aussi la meilleure université de France.","Mes études se passent bien. Les études sont un peu difficiles mais je fais bien dans mes études. J'ai obtenu de bonnes notes à l'examen du premier semestre. Mes professeurs sont très contents de mes progrès.","Les cours sont exigeants mais passionnants.","L'environnement de l'université est très amical. J'ai aussi une amie indienne. Elle est très sympa. Elle m'aide toujours aux études. Nous étudions et nous jouons ensemble.","Nous travaillons à la bibliothèque et nous nous promenons au Quartier latin.","Je fais des achats dans un supermarché près de l'université. La vie ici est très excitante. Je suis très content de ma vie.","Comment est maman ? Donne-lui mes salutations. Réponds-moi vite. J'attends ta lettre."],"closing":["Ton fils,"],"signature":"Manuel"},"en":{"date":"Paris, 5 July 2025","salutation":"Dear Dad,","paras":["How are you? I have settled in well in Paris and I wanted to give you my news.","I am at the University of the Sorbonne. It is the oldest university in Paris, founded by Robert de Sorbonne in 1257. It is also the best university in France.","My studies are going well. The work is a little difficult but I am doing well in my studies. I got good marks in the first semester exam. My teachers are very pleased with my progress.","The classes are demanding but fascinating.","The atmosphere at the university is very friendly. I also have an Indian friend. She is very nice. She always helps me with my studies. We study and play together.","We work in the library and we go for walks in the Latin Quarter.","I do my shopping in a supermarket near the university. Life here is very exciting. I am very happy with my life.","How is Mum? Give her my regards. Write back quickly. I am waiting for your letter."],"closing":["Your son,"],"signature":"Manuel"}},"vocab":[["créée par Robert de Sorbonne en 1257","founded by Robert de Sorbonne in 1257"],["la plus ancienne université de Paris","the oldest university in Paris"],["la meilleure université de France","the best university in France"],["l'examen du premier semestre","the first semester exam"],["mes professeurs sont contents de mes progrès","my teachers are pleased with my progress"],["un supermarché près de l'université","a supermarket near the university"],["le Quartier latin","the Latin Quarter"]],"bank":[["C'est la plus ancienne université de Paris.","It is the oldest university in Paris."],["Mes études se passent bien.","My studies are going well."],["J'ai obtenu de bonnes notes à l'examen du premier semestre.","I got good marks in the first semester exam."],["L'environnement de l'université est très amical.","The university atmosphere is very friendly."],["La vie ici est très excitante.","Life here is very exciting."]],"notes":["Corrections : « C'est une plus ancienne université » → « la plus ancienne » (le superlatif prend l'article défini) ; « crée » → « créée » ; « Je fais de l'achat » → « Je fais des achats » ; date complétée (mois en minuscule, année ajoutée) ; virgule après l'appel.","Ajouts : « Les cours sont exigeants mais passionnants » et la phrase sur la bibliothèque et le Quartier latin ne sont pas dans la lettre d'origine.","La traduction anglaise d'origine signait « Manual » et traduisait « Donne-lui mes salutations » par « Give him my regards » alors qu'il s'agit de maman — corrigé ici."]},{"id":"let-secretaire","kind":"letter","lecon":"Ch 4","fr":{"title":"Un poste de secrétaire est libre"},"en":{"title":"A Secretary Post Is Free"},"prompt":{"fr":"Votre ami(e) travaille dans un bureau où un poste de secrétaire est libre. Il/Elle vous écrit d'y postuler en décrivant le travail, le bureau, les collègues, etc. Rédigez cette lettre.","en":"Your friend works in an office where a secretary post is free. He/She writes telling you to apply, describing the work, the office, the colleagues and so on. Write this letter."},"years":[],"letter":{"fr":{"date":"Paris, le 14 septembre 2025","salutation":"Chère Neha,","paras":["Comment ça va ? Je vais bien ici. Ça fait longtemps que je ne t'ai pas écrit. Dans cette lettre, je vais te parler du travail de ton choix.","J'ai une bonne nouvelle pour toi !","Un poste de secrétaire est libre dans l'entreprise où je travaille. C'est le travail dont tu seras contente, parce que le travail de secrétaire est un peu du travail intellectuel et manuel.","Tu dois prendre des notes que tu dois rédiger sous forme de lettres sur l'ordinateur. Tu tapes des textes que tu dois imprimer sur l'imprimante. Tu ranges les dossiers et tu fais des photocopies. Il y a beaucoup de choses à faire mais c'est un travail intéressant.","Ensuite, le bureau est clair et bien équipé.","En plus, le directeur est génial. Le chef et les collègues sont très sympas et bons.","Discute de ce travail avec tes parents et essaie de poser ta candidature dans les meilleurs délais. Bonne chance ! Tu me manques."],"closing":["Amitiés,"],"signature":"Akansha"},"en":{"date":"Paris, 14 September 2025","salutation":"Dear Neha,","paras":["How are you? I am fine here. It has been a long time since I wrote to you. In this letter I am going to tell you about the job you would choose.","I have good news for you!","A secretary post is free at the company where I work. It is the job you will be happy with, because a secretary's work is partly intellectual and partly manual.","You have to take notes which you then write up as letters on the computer. You type texts which you have to print on the printer. You file the folders and you make photocopies. There is a lot to do but it is interesting work.","The office is bright and well equipped too.","What is more, the director is great. The head of department and the colleagues are very friendly and good.","Talk this job over with your parents and try to apply as soon as possible. Good luck! I miss you."],"closing":["Best wishes,"],"signature":"Akansha"}},"vocab":[["un poste est libre","a post is vacant"],["du travail intellectuel et manuel","intellectual and manual work"],["prendre des notes","to take notes"],["taper des textes","to type texts"],["imprimer sur l'imprimante","to print on the printer"],["ranger les dossiers","to file the folders"],["faire des photocopies","to make photocopies"],["le directeur, le chef, les collègues","the director, the head, the colleagues"]],"bank":[["Un poste de secrétaire est libre dans l'entreprise où je travaille.","A secretary post is free at the company where I work."],["C'est le travail dont tu seras contente.","It is the job you will be happy with."],["Tu tapes des textes que tu dois imprimer sur l'imprimante.","You type texts you have to print on the printer."],["Il y a beaucoup de choses à faire mais c'est un travail intéressant.","There is a lot to do but it is interesting work."],["Le chef et les collègues sont très sympas et bons.","The head and the colleagues are very friendly and good."]],"notes":["Corrections : « une poste » → « un poste » (une poste = le bureau de poste) ; « d'y joindre » → « d'y postuler » ; « des notes que dois rédiger » → « que tu dois rédiger » ; « Discute de ce travail à tes parents » → « avec tes parents » ; date complétée ; virgules ajoutées.","La lettre d'origine ne décrit jamais le bureau, alors que le sujet le demande — la phrase « le bureau est clair et bien équipé » est un ajout qui comble ce manque.","« Tu me manques » n'est pas une formule de politesse : la ligne est conservée dans le corps et « Amitiés, » sert de clôture."]},{"id":"let-roman","kind":"letter","lecon":"Ch 4","fr":{"title":"Un roman récent"},"en":{"title":"A Book You Have Read"},"prompt":{"fr":"Vous venez de lire un roman intéressant. Écrivez une lettre à votre cousin en racontant l'histoire.","en":"You have just read an interesting novel. Write a letter to your cousin telling the story."},"years":[],"letter":{"fr":{"date":"Delhi, le 14 février 2021","salutation":"Cher cousin,","paras":["Salut ! Comment vas-tu ? Ça fait longtemps que je ne t'ai pas écrit. Dans cette lettre, je te raconte l'histoire d'un roman que je viens de lire.","Le roman s'appelle « 2 STATES », écrit par un écrivain indien, Chetan Bhagat. Il s'agit d'un garçon du Punjab et d'une fille du Tamil Nadu. Ils étudient ensemble à l'université. Au fur et à mesure, ils commencent à s'aimer.","Après leurs études, ils décident de se marier mais les familles sont contre cette idée. Donc, ils essaient de convaincre leurs parents. Tout y est : le drame, la comédie et l'amour.","Toi aussi, tu as lu un roman intéressant ? Écris-moi vite !"],"closing":["Bises,"],"signature":"XYZ"},"en":{"date":"Delhi, 14 February 2021","salutation":"Dear cousin,","paras":["Hi! How are you? It has been a long time since I wrote to you. In this letter I am telling you the story of a novel I have just read.","The novel is called \"2 STATES\", written by an Indian writer, Chetan Bhagat. It is about a boy from Punjab and a girl from Tamil Nadu. They study together at university. Gradually they begin to love each other.","After their studies they decide to get married, but the families are against the idea. So they try to convince their parents. It is all there: drama, comedy and love.","Have you read an interesting novel too? Write back soon!"],"closing":["Love,"],"signature":"XYZ"}},"vocab":[["un roman","a novel"],["un écrivain indien","an Indian writer"],["il s'agit de…","it is about…"],["au fur et à mesure","gradually"],["se marier","to get married"],["convaincre leurs parents","to convince their parents"],["le drame, la comédie et l'amour","drama, comedy and love"]],"bank":[["Je te raconte l'histoire d'un roman que je viens de lire.","I am telling you the story of a novel I have just read."],["Il s'agit d'un garçon du Punjab et d'une fille du Tamil Nadu.","It is about a boy from Punjab and a girl from Tamil Nadu."],["Au fur et à mesure, ils commencent à s'aimer.","Gradually they begin to love each other."],["Tout y est : le drame, la comédie et l'amour.","It is all there: drama, comedy and love."]],"notes":["Corrections : phrase trop longue coupée après « écrit » ; « Toi aussi, tu as aussi lu » → « Toi aussi, tu as lu » ; « Bisou ! » → « Bises, » (virgule exigée après la formule de politesse) ; virgule après l'appel.","Cette lettre et celle du film (Ch 5) sont deux versions jumelles de la même histoire, « 2 STATES »."]},{"id":"let-biblio","kind":"letter","lecon":"Ch 4","fr":{"title":"Une visite à la bibliothèque"},"en":{"title":"A Visit to the Library"},"prompt":{"fr":"Vous êtes en France. Vous avez visité une bibliothèque à Paris. Écrivez une lettre à vos parents décrivant votre visite.","en":"You are in France. You visited a library in Paris. Write a letter to your parents describing your visit."},"years":["CBSE 2024","CBSE 2023"],"letter":{"fr":{"date":"Paris, le 21 janvier 2022","salutation":"Chers papa et maman,","paras":["Comment allez-vous ? Je vais bien ici. Je me suis bien installé à Paris. L'université est très grande et belle. Mes camarades sont sympathiques aussi. Hier, j'ai visité une bibliothèque avec eux.","Pour avoir une carte de lecteur, il faut avoir une pièce d'identité, une autorisation des parents et une quittance d'électricité ou de loyer.","Avec la carte de lecteur, on peut emporter des CD, des DVD, des bandes dessinées, des jeux vidéo, des livres d'images, etc. chez soi et on peut aussi travailler sur place.","Elle propose aussi des romans et des magazines.","Je me suis beaucoup amusé à la bibliothèque."],"closing":["Bises,"],"signature":"XYZ"},"en":{"date":"Paris, 21 January 2022","salutation":"Dear Mum and Dad,","paras":["How are you both? I am fine here. I have settled in well in Paris. The university is very big and beautiful. My classmates are friendly too. Yesterday I visited a library with them.","To get a reader's card you need an identity document, a parent's authorisation and an electricity or rent receipt.","With the reader's card you can take home CDs, DVDs, comics, video games, picture books and so on, and you can also work there on the spot.","It also offers novels and magazines.","I really enjoyed myself at the library."],"closing":["Love,"],"signature":"XYZ"}},"vocab":[["la carte de lecteur","the reader's card"],["une pièce d'identité","an identity document"],["une autorisation des parents","a parent's authorisation"],["une quittance d'électricité ou de loyer","an electricity or rent receipt"],["emporter chez soi","to take home"],["des bandes dessinées, des livres d'images","comics, picture books"],["travailler sur place","to work there on the spot"]],"bank":[["Pour avoir une carte de lecteur, il faut avoir une pièce d'identité.","To get a reader's card you need an identity document."],["On peut emporter des CD, des DVD et des bandes dessinées chez soi.","You can take home CDs, DVDs and comics."],["On peut aussi travailler sur place.","You can also work there on the spot."],["Je me suis beaucoup amusé à la bibliothèque.","I really enjoyed myself at the library."]],"notes":["Ici « vous » est CORRECT — la lettre s'adresse à deux personnes (papa ET maman). C'est la seule situation où « vous » ne coûte pas le point de registre.","Ajout : « Elle propose aussi des romans et des magazines » n'est pas dans la lettre d'origine.","Grammaire à montrer : le passé composé des verbes pronominaux (« je me suis installé », « je me suis amusé »)."]},{"id":"let-film","kind":"letter","lecon":"Ch 5","fr":{"title":"Un film récent"},"en":{"title":"A Film You Have Seen"},"prompt":{"fr":"Vous venez de regarder un film intéressant. Écrivez une lettre à votre cousin en racontant l'histoire.","en":"You have just watched an interesting film. Write a letter to your cousin telling the story."},"years":[],"letter":{"fr":{"date":"Delhi, le 14 février 2021","salutation":"Cher cousin,","paras":["Salut ! Comment vas-tu ? Ça fait longtemps que je ne t'ai pas écrit. Dans cette lettre, je te raconte l'histoire d'un film que je viens de regarder.","Le film s'appelle « 2 STATES ». Alia Bhatt et Arjun Kapoor sont les acteurs principaux. Il s'agit d'un garçon du Punjab et d'une fille du Tamil Nadu. Ils étudient ensemble à l'université. Au fur et à mesure, ils commencent à s'aimer.","Après leurs études, ils décident de se marier mais les familles sont contre cette idée. Donc, ils essaient de convaincre leurs parents. Tout y est : le drame, la comédie et l'amour.","Tu devrais le voir, tu l'aimeras !","Toi aussi, tu as regardé un film intéressant ? Écris-moi vite !"],"closing":["Bises,"],"signature":"XYZ"},"en":{"date":"Delhi, 14 February 2021","salutation":"Dear cousin,","paras":["Hi! How are you? It has been a long time since I wrote to you. In this letter I am telling you the story of a film I have just watched.","The film is called \"2 STATES\". Alia Bhatt and Arjun Kapoor are the lead actors. It is about a boy from Punjab and a girl from Tamil Nadu. They study together at university. Gradually they begin to love each other.","After their studies they decide to get married, but the families are against the idea. So they try to convince their parents. It is all there: drama, comedy and love.","You should see it, you will love it!","Have you watched an interesting film too? Write back soon!"],"closing":["Love,"],"signature":"XYZ"}},"vocab":[["les acteurs principaux","the lead actors"],["il s'agit de…","it is about…"],["au fur et à mesure","gradually"],["être contre cette idée","to be against the idea"],["convaincre","to convince"],["le drame, la comédie et l'amour","drama, comedy and love"]],"bank":[["Le film s'appelle « … ».","The film is called…"],["Alia Bhatt et Arjun Kapoor sont les acteurs principaux.","Alia Bhatt and Arjun Kapoor are the lead actors."],["Tout y est : le drame, la comédie et l'amour.","It is all there: drama, comedy and love."],["Tu devrais le voir, tu l'aimeras !","You should see it, you will love it!"]],"notes":["Corrections : mêmes fautes que la lettre « roman » ; « Bisou ! » → « Bises, » ; virgule après l'appel.","Ajout : « Tu devrais le voir, tu l'aimeras ! » n'est pas dans la lettre d'origine.","Lettre jumelle de « Un roman récent » (Ch 4) : même histoire, même date, même destinataire."]},{"id":"let-emission","kind":"letter","lecon":"Ch 5","fr":{"title":"Mon émission préférée"},"en":{"title":"My Favourite TV Programme"},"prompt":{"fr":"Écrivez à votre ami(e) de votre émission préférée.","en":"Write to your friend about your favourite TV programme."},"years":[],"letter":{"fr":{"date":"Koweït, le 11 septembre 2025","salutation":"Cher Luc,","paras":["Comment vas-tu ? J'espère que cette lettre te trouvera en bonne santé.","Dans cette lettre, je voudrais t'écrire au sujet de mon émission préférée. Je regarde souvent la télé et j'aime beaucoup l'émission sportive « Football Today ».","Dans cette émission, le présentateur parle des actualités du football et commente les matchs. J'aime beaucoup son analyse et je ne manque jamais cette émission.","Dis bonjour à tes parents. Écris-moi vite."],"closing":["Ton ami,"],"signature":"Karan"},"en":{"date":"Kuwait, 11 September 2025","salutation":"Dear Luc,","paras":["How are you? I hope this letter finds you in good health.","In this letter I would like to write to you about my favourite programme. I often watch television and I really like the sports show \"Football Today\".","On this programme, the presenter talks about football news and comments on the matches. I really like his analysis and I never miss this show.","Say hello to your parents. Write back soon."],"closing":["Your friend,"],"signature":"Karan"}},"vocab":[["une émission","a TV programme"],["le présentateur","the presenter"],["les actualités","the news"],["commenter les matchs","to comment on the matches"],["une chaîne","a TV channel"],["zapper","to channel-hop"]],"bank":[["Mon émission préférée s'appelle…","My favourite programme is called…"],["Le présentateur parle des actualités.","The presenter talks about the news."],["Je ne manque jamais cette émission.","I never miss this programme."]],"notes":["Cette lettre n'a pas de fichier source dans le dossier : elle a été rédigée pour compléter le programme de la Leçon 5.","Vocabulaire de Section D réutilisable : ARTE (chaîne culturelle), Canal+, VO = version originale, un feuilleton, un quotidien, un hebdomadaire."]},{"id":"let-loisirs","kind":"letter","lecon":"Ch 6","fr":{"title":"Mon passe-temps favori"},"en":{"title":"My Favourite Hobby"},"prompt":{"fr":"Écrivez une lettre à votre ami(e) pour lui parler de votre passe-temps favori.","en":"Write a letter to your friend telling them about your favourite hobby."},"years":["CBSE 2025","CBSE 2023"],"letter":{"fr":{"date":"Ahmadi, le 21 août 2025","salutation":"Cher Pierre,","paras":["Comment vas-tu ? J'espère que tu es en bonne santé. Moi, je vais bien.","Tu sais, mon passe-temps favori est la lecture. J'aime lire des romans français et des magazines. Chaque soir, après mes devoirs, je passe une heure à lire. Cela me détend et m'aide aussi à améliorer mon vocabulaire.","Le week-end, j'aime regarder des films en français avec mes amis. C'est amusant et très utile pour comprendre la prononciation.","Et toi, quel est ton passe-temps favori ? Écris-moi vite."],"closing":["Ton amie,"],"signature":"Sophie"},"en":{"date":"Ahmadi, 21 August 2025","salutation":"Dear Pierre,","paras":["How are you? I hope you are in good health. I am well.","You know, my favourite hobby is reading. I like reading French novels and magazines. Every evening, after my homework, I spend an hour reading. It relaxes me and it also helps me improve my vocabulary.","At weekends I like watching French films with my friends. It is fun and very useful for understanding pronunciation.","And you, what is your favourite hobby? Write back soon."],"closing":["Your friend,"],"signature":"Sophie"}},"vocab":[["un passe-temps favori","a favourite hobby"],["la lecture","reading"],["cela me détend","it relaxes me"],["améliorer mon vocabulaire","to improve my vocabulary"],["le jardinage","gardening"],["les tâches ménagères","housework"]],"bank":[["Mon passe-temps favori est la lecture.","My favourite hobby is reading."],["Chaque soir, je passe une heure à lire.","Every evening I spend an hour reading."],["Cela me détend.","It relaxes me."],["Et toi, quel est ton passe-temps favori ?","And you, what is your favourite hobby?"]],"notes":["Cette lettre n'a pas de fichier source dans le dossier : elle a été rédigée parce que le sujet « vos loisirs préférés » est tombé en 2023 et en 2025.","Le sujet le plus libre du programme : vous choisissez le contenu. Préparez UN loisir à fond plutôt que cinq vaguement."]},{"id":"let-malade","kind":"letter","lecon":"Ch 7","fr":{"title":"Conseils à un ami malade"},"en":{"title":"Advice to a Sick Friend"},"prompt":{"fr":"Votre ami est malade et vous lui conseillez en écrivant une lettre.","en":"Your friend is ill and you advise him by writing a letter."},"years":["CBSE 2025","CBSE 2024","CBSE 2022","CBSE 2019"],"letter":{"fr":{"date":"Delhi, le 21 janvier 2021","salutation":"Cher ABC,","paras":["Je viens de savoir que tu ne vas pas bien. Qu'est-ce qui se passe ? Je sais que tu es très stressé à cause des examens.","Mais mon ami, n'oublie pas que celui qui a la santé est riche sans le savoir.","Il faut manger des fruits et des légumes, boire beaucoup d'eau, faire du yoga ou d'autres exercices physiques pour rester en pleine forme. Prends tes médicaments à l'heure !","D'abord, il faut que tu te reposes bien et que tu dormes huit heures par nuit. Évite le fast-food, c'est mauvais pour la santé.","Si la fièvre continue, va chez le médecin. Un peu de marche chaque matin te fera du bien.","Je ferai des plans pour te visiter dès que possible.","Prends soin de toi !"],"closing":["Ton ami,"],"signature":"XYZ"},"en":{"date":"Delhi, 21 January 2021","salutation":"Dear ABC,","paras":["I have just heard that you are not well. What is happening? I know you are very stressed because of the exams.","But my friend, do not forget that the person who has health is rich without knowing it.","You need to eat fruit and vegetables, drink plenty of water, and do yoga or other physical exercise to stay in great shape. Take your medicine on time!","First of all, you need to rest properly and sleep eight hours a night. Avoid fast food, it is bad for your health.","If the fever continues, go to the doctor. A short walk every morning will do you good.","I will make plans to come and visit you as soon as possible.","Take care of yourself!"],"closing":["Your friend,"],"signature":"XYZ"}},"vocab":[["être stressé à cause des examens","to be stressed because of exams"],["celui qui a la santé est riche sans le savoir","the person who has health is rich without knowing it"],["des fruits et des légumes","fruit and vegetables"],["faire du yoga","to do yoga"],["des exercices physiques","physical exercise"],["rester en pleine forme","to stay in great shape"],["prendre ses médicaments à l'heure","to take your medicine on time"]],"bank":[["Je viens de savoir que tu ne vas pas bien.","I have just heard that you are not well."],["Celui qui a la santé est riche sans le savoir.","The person who has health is rich without knowing it."],["Il faut manger des fruits et des légumes, boire beaucoup d'eau.","You need to eat fruit and vegetables and drink plenty of water."],["Prends tes médicaments à l'heure !","Take your medicine on time!"],["Je ferai des plans pour te visiter dès que possible.","I will make plans to visit you as soon as possible."],["Prends soin de toi !","Take care of yourself!"]],"notes":["LE SUJET LE PLUS POSÉ — quatre fois en six copies (2019, 2022, 2024, 2025). À préparer en priorité.","ATTENTION — deux explications coexistent volontairement : la lettre d'origine dit que l'ami est stressé à cause des examens, l'ajout parle de fièvre et d'aller chez le médecin. Choisissez l'une des deux quand vous rédigez.","Le proverbe « celui qui a la santé est riche sans le savoir » est le cœur de la lettre d'origine : apprenez-le, il impressionne le correcteur.","Corrections : virgule supprimée avant l'année (« le 21 janvier, 2021 ») ; « Yoga » → « yoga » ; virgule ajoutée après l'appel."]},{"id":"let-maladie-recit","kind":"letter","lecon":"Ch 7","fr":{"title":"Raconter sa maladie"},"en":{"title":"Telling the Story of Your Illness"},"prompt":{"fr":"Vous étiez malade. Maintenant vous êtes guéri. Écrivez une lettre à votre mère décrivant ce qui s'est passé.","en":"You were ill. Now you are better. Write a letter to your mother describing what happened."},"years":[],"letter":{"fr":{"date":"Delhi, le 21 janvier 2022","salutation":"Chère maman,","paras":["J'écris cette lettre pour vous dire une bonne nouvelle. Vous ne savez pas que j'étais malade.","Je souffrais d'un rhume et d'un nez qui coulait. À cause de cela, j'avais de la fièvre et des problèmes de respiration.","Je toussais et je dormais très mal.","Je suis allé chez le médecin et il m'a prescrit des médicaments. Ne vous inquiétez pas ! Maintenant, je vais bien.","Pour rester en pleine forme, j'ai commencé à bien manger, bien dormir et faire du yoga.","J'attends votre lettre ! Vous me manquez !"],"closing":["Bises,"],"signature":"XYZ"},"en":{"date":"Delhi, 21 January 2022","salutation":"Dear Mum,","paras":["I am writing this letter to give you some good news. You do not know that I was ill.","I was suffering from a cold and a runny nose. Because of that, I had a fever and breathing problems.","I was coughing and sleeping very badly.","I went to the doctor and he prescribed me some medicine. Do not worry! I am fine now.","To stay in great shape, I have started eating well, sleeping well and doing yoga.","I am waiting for your letter! I miss you!"],"closing":["Love,"],"signature":"XYZ"}},"vocab":[["souffrir d'un rhume","to suffer from a cold"],["un nez qui coulait","a runny nose"],["des problèmes de respiration","breathing problems"],["prescrire des médicaments","to prescribe medicine"],["rester en pleine forme","to stay in great shape"],["faire du yoga","to do yoga"]],"bank":[["Je souffrais d'un rhume et d'un nez qui coulait.","I was suffering from a cold and a runny nose."],["À cause de cela, j'avais de la fièvre.","Because of that, I had a fever."],["Il m'a prescrit des médicaments.","He prescribed me some medicine."],["Ne vous inquiétez pas ! Maintenant, je vais bien.","Do not worry! I am fine now."],["Pour rester en pleine forme, j'ai commencé à bien manger.","To stay in shape I started eating well."]],"notes":["REGISTRE — la lettre d'origine vouvoie la mère du début à la fin (« Vous ne savez pas », « Ne vous inquiétez pas », « Vous me manquez »). C'est cohérent et respecté ici. Mais l'examen attend « tu » dans une lettre familiale : à l'épreuve, tutoyez.","LETTRE NARRATIVE — l'imparfait plante le décor (je souffrais, j'avais, je toussais), le passé composé raconte les événements (je suis allé, il m'a prescrit), le présent dit que tout va bien maintenant.","Ajout : « Je toussais et je dormais très mal » n'est pas dans la lettre d'origine."]},{"id":"let-nuit-blanche","kind":"letter","lecon":"Ch 7","fr":{"title":"Une nuit blanche"},"en":{"title":"A Sleepless Night"},"prompt":{"fr":"Hier, vous avez passé une nuit blanche. Écrivez une lettre à votre ami(e) en donnant la raison de ce qui s'est passé.","en":"Yesterday you had a sleepless night. Write a letter to your friend explaining what happened to you."},"years":[],"letter":{"fr":{"date":"Paris, le 14 septembre 2025","salutation":"Chère Lavanya,","paras":["Comment ça va ? Je vais bien ici. Ça fait longtemps que je ne t'ai pas écrit parce que je m'étais occupée pour l'examen. Dans cette lettre, je vais te dire comment j'ai passé une nuit blanche après l'examen.","Hier, je n'ai pas pu dormir à cause du stress et de la maladie. J'avais de la fièvre et des problèmes de respiration. Après avoir pris des médicaments, je n'étais pas confortable.","Il était minuit et je révisais encore. J'avais mal à la tête et chaque bruit me réveillait.","J'ai essayé de dormir en tournant autour du lit, j'ai voulu me détendre en lisant des livres et en regardant la télé mais malheureusement rien ne m'a remise. J'ai commencé à partir dans des rêveries. Toute la nuit s'est passée comme ça.","Donc le matin à 4 heures, j'ai pu dormir grâce au yoga suivi de 10 minutes de méditation.","Ça s'est passé peut-être à cause de l'examen la semaine dernière, parce que j'avais étudié dur et je n'avais pas bien mangé non plus.","Prends bien soin de toi ! Donne mes salutations à tes parents."],"closing":["Bises,"],"signature":"XYZ"},"en":{"date":"Paris, 14 September 2025","salutation":"Dear Lavanya,","paras":["How are you? I am fine here. It has been a long time since I wrote to you because I was busy with the exam. In this letter I am going to tell you how I spent a sleepless night after the exam.","Yesterday I could not sleep because of stress and illness. I had a fever and breathing problems. After taking medicine, I was not comfortable.","It was midnight and I was still revising. I had a headache and every noise woke me up.","I tried to sleep by rolling around in bed, I wanted to relax by reading books and watching TV, but unfortunately nothing helped. I started drifting off into daydreams. The whole night went like that.","So in the morning at four o'clock I was able to sleep, thanks to yoga followed by ten minutes of meditation.","It probably happened because of the exam last week, because I had studied hard and I had not eaten well either.","Take good care of yourself! Give my regards to your parents."],"closing":["Love,"],"signature":"XYZ"}},"vocab":[["une nuit blanche","a sleepless night"],["à cause du stress et de la maladie","because of stress and illness"],["des problèmes de respiration","breathing problems"],["en tournant autour du lit","rolling around in bed"],["partir dans des rêveries","to drift off into daydreams"],["le yoga suivi de 10 minutes de méditation","yoga followed by 10 minutes of meditation"],["j'avais étudié dur","I had studied hard"]],"bank":[["Je n'ai pas pu dormir à cause du stress et de la maladie.","I could not sleep because of stress and illness."],["Après avoir pris des médicaments, je n'étais pas confortable.","After taking medicine I was not comfortable."],["J'ai essayé de dormir en tournant autour du lit.","I tried to sleep by rolling around in bed."],["J'ai pu dormir grâce au yoga suivi de 10 minutes de méditation.","I was able to sleep thanks to yoga and ten minutes of meditation."],["J'avais étudié dur et je n'avais pas bien mangé.","I had studied hard and had not eaten well."]],"notes":["Corrections nombreuses : « passe » → « passé » (trois fois) ; « Apres » → « Après » ; « a votre / a 4 heures / a tes parents » → « à » ; « rien m'a remis » → « rien ne m'a remise » ; « Toute la nuit s'est passé » → « passée » ; date complétée.","ATTENTION — deux chronologies coexistent volontairement : la lettre d'origine situe la nuit blanche APRÈS l'examen, l'ajout la situe pendant les révisions (« Il était minuit et je révisais encore »). Choisissez l'une des deux quand vous rédigez.","La raison demandée par le sujet est donnée dans l'avant-dernier paragraphe : l'examen, avoir étudié dur, avoir mal mangé."]},{"id":"let-environnement","kind":"letter","lecon":"Ch 8","fr":{"title":"Protéger l'environnement"},"en":{"title":"Protecting the Environment"},"prompt":{"fr":"Écrivez une lettre à votre cousin/cousine pour lui dire ce qu'il/elle peut faire pour protéger l'environnement.","en":"Write a letter to your cousin saying what he/she can do to protect the environment."},"years":[],"letter":{"fr":{"date":"Delhi, le 21 janvier 2022","salutation":"Cher Denis,","paras":["J'ai reçu ta lettre dans laquelle tu m'as demandé mes idées pour sauver notre planète. Voici mes suggestions.","Pour assurer la survie et donc l'avenir de l'humanité, il est indispensable de protéger l'environnement. Tout ce que nous mangeons et buvons provient de la nature, alors il faut protéger notre source de nourriture et d'eau potable.","Il faut limiter notre impact sur le climat en réduisant nos rejets de gaz à effet de serre. On doit recycler les objets. On peut acheter des produits durables et réutilisables. On peut réduire l'utilisation de sacs en plastique. Il faut réduire l'usage de l'électricité en éteignant les appareils inutilement allumés.","De plus, nous devons réduire le gaspillage et la pollution. Ferme le robinet quand tu n'en as pas besoin.","J'espère que tu aimes mes idées pour sauver notre planète. Réponds-moi !"],"closing":["Ton ami,"],"signature":"Anirudh"},"en":{"date":"Delhi, 21 January 2022","salutation":"Dear Denis,","paras":["I received your letter in which you asked me for my ideas to save our planet. Here are my suggestions.","To ensure the survival and therefore the future of humanity, it is essential to protect the environment. Everything we eat and drink comes from nature, so we must protect our source of food and drinking water.","We must limit our impact on the climate by reducing our greenhouse gas emissions. We have to recycle objects. We can buy durable and reusable products. We can reduce the use of plastic bags. We must cut down on electricity by switching off appliances that are left on unnecessarily.","What is more, we must reduce waste and pollution. Turn off the tap when you do not need it.","I hope you like my ideas for saving our planet. Write back to me!"],"closing":["Your friend,"],"signature":"Anirudh"}},"vocab":[["la survie et l'avenir de l'humanité","the survival and future of humanity"],["notre source de nourriture et d'eau potable","our source of food and drinking water"],["les rejets de gaz à effet de serre","greenhouse gas emissions"],["recycler les objets","to recycle objects"],["des produits durables et réutilisables","durable and reusable products"],["les sacs en plastique","plastic bags"],["éteindre les appareils inutilement allumés","switch off appliances left on needlessly"]],"bank":[["Il est indispensable de protéger l'environnement.","It is essential to protect the environment."],["Tout ce que nous mangeons et buvons provient de la nature.","Everything we eat and drink comes from nature."],["Il faut limiter notre impact sur le climat.","We must limit our impact on the climate."],["On peut acheter des produits durables et réutilisables.","We can buy durable and reusable products."],["J'espère que tu aimes mes idées pour sauver notre planète.","I hope you like my ideas for saving our planet."]],"notes":["Ajout : « nous devons réduire le gaspillage et la pollution » et « Ferme le robinet » ne sont pas dans la lettre d'origine.","Corrections : virgule ajoutée après l'appel ; « alors, il faut » → « alors il faut ».","Grammaire à montrer : « il est indispensable de » + infinitif, « il faut » + infinitif, l'impératif (« Ferme »)."]},{"id":"let-politique-fr","kind":"letter","lecon":"Ch 10","fr":{"title":"Le système politique français"},"en":{"title":"The Political System of France"},"prompt":{"fr":"Vous écrivez une lettre à un ami français expliquant le système politique en France.","en":"You write a letter to a French friend explaining the political system in France."},"years":["CBSE 2025","CBSE 2019","CBSE 2017"],"letter":{"fr":{"date":"Paris, le 21 janvier 2025","salutation":"Cher Nikhil,","paras":["Comment ça va ? Je vais bien ici en France. Ça fait longtemps que je ne t'ai pas écrit. Dans cette lettre, je vais te parler du système politique en France.","Le Parlement français se compose de deux assemblées : l'Assemblée nationale et le Sénat. Les membres de l'Assemblée nationale, les députés, sont élus par le peuple. Le palais Bourbon est le siège de l'Assemblée nationale. Les membres du Sénat s'appellent les sénateurs. Le palais du Luxembourg est le siège du Sénat.","Le Président français est élu par les citoyens pour cinq ans. Situé au cœur de Paris, près des Champs-Élysées, le palais de l'Élysée est l'endroit où travaille et vit le Président. Le Président de la République française s'appelle Emmanuel Macron.","Le Président de la République française a beaucoup de responsabilités : il représente le pays tout entier. Quand il voyage officiellement à l'étranger, il parle au nom de la France et de tous les Français. Il nomme les hautes personnalités de l'État : le Premier ministre et les ambassadeurs. Il est le chef des armées.","Il préside aussi le Conseil des ministres. La devise de la République est « Liberté, Égalité, Fraternité ».","Décris-moi le système politique de ton pays."],"closing":["Ton ami,"],"signature":"Jacques"},"en":{"date":"Paris, 21 January 2025","salutation":"Dear Nikhil,","paras":["How are you? I am doing well here in France. It has been a long time since I wrote to you. In this letter I am going to tell you about the political system in France.","The French Parliament is made up of two assemblies: the National Assembly and the Senate. The members of the National Assembly, the deputies, are elected by the people. The Palais Bourbon is the seat of the National Assembly. The members of the Senate are called senators. The Luxembourg Palace is the seat of the Senate.","The French President is elected by the citizens for five years. Located in the heart of Paris, near the Champs-Élysées, the Élysée Palace is where the President works and lives. The President of the French Republic is called Emmanuel Macron.","The President of the French Republic has many responsibilities: he represents the whole country. When he travels officially abroad, he speaks in the name of France and of all French people. He appoints the senior figures of the State: the Prime Minister and the ambassadors. He is the head of the armed forces.","He also chairs the Council of Ministers. The motto of the Republic is \"Liberty, Equality, Fraternity\".","Describe the political system of your country to me."],"closing":["Your friend,"],"signature":"Jacques"}},"vocab":[["deux assemblées : l'Assemblée nationale et le Sénat","two assemblies"],["les députés, élus par le peuple","the deputies, elected by the people"],["le palais Bourbon","seat of the National Assembly"],["les sénateurs","the senators"],["le palais du Luxembourg","seat of the Senate"],["près des Champs-Élysées","near the Champs-Élysées"],["il nomme les hautes personnalités de l'État","he appoints the senior figures of the State"],["le Premier ministre et les ambassadeurs","the Prime Minister and the ambassadors"],["il est le chef des armées","he is the head of the armed forces"]],"bank":[["Le Parlement français se compose de deux assemblées.","The French Parliament is made up of two assemblies."],["Les députés sont élus par le peuple.","The deputies are elected by the people."],["Le Président français est élu par les citoyens pour cinq ans.","The French President is elected by the citizens for five years."],["Il représente le pays tout entier.","He represents the whole country."],["Quand il voyage à l'étranger, il parle au nom de la France.","When he travels abroad he speaks in the name of France."],["Il nomme le Premier ministre et les ambassadeurs.","He appoints the Prime Minister and the ambassadors."],["Il est le chef des armées.","He is the head of the armed forces."]],"notes":["CETTE LETTRE SERT DEUX FOIS : les quatre responsabilités du Président — représenter le pays, parler au nom de la France à l'étranger, nommer le Premier ministre et les ambassadeurs, être le chef des armées — répondent mot pour mot à la question de Section D « Quelles sont les responsabilités du Président français ? », posée en 2019, 2020, 2023, 2024 et 2025.","Ne confondez pas les trois palais : l'Élysée = le Président, le palais Bourbon = l'Assemblée nationale, le palais du Luxembourg = le Sénat.","Ajout : « Il préside aussi le Conseil des ministres » et la devise « Liberté, Égalité, Fraternité » ne sont pas dans la lettre d'origine.","Nommer le président en exercice date la copie : « Emmanuel Macron » est conservé parce qu'il est dans l'original, mais vous pouvez l'omettre à l'examen."]},{"id":"let-politique-in","kind":"letter","lecon":"Ch 10","fr":{"title":"Le système politique indien"},"en":{"title":"The Political System of India"},"prompt":{"fr":"Vous écrivez une lettre à un ami français expliquant le système politique en Inde.","en":"You write a letter to a French friend explaining the political system in India."},"years":[],"letter":{"fr":{"date":"Delhi, le 21 janvier 2022","salutation":"Cher Denis,","paras":["Merci pour ta lettre dans laquelle tu m'as expliqué le système politique de la France. Je vais te décrire le système politique en Inde.","Comme en France, le parlement se compose de deux chambres : la Lok Sabha et la Rajya Sabha. Le peuple élit les membres de la Lok Sabha.","Le chef du parti politique qui gagne une majorité des voix devient le Premier ministre et lui à son tour choisit les autres ministres. En Inde, c'est le Premier ministre qui est le chef du gouvernement.","Les élections présidentielles sont différentes en Inde. Le président est élu par les membres du parlement et de l'assemblée législative des états.","Et chez toi, qui a le plus de pouvoir ?"],"closing":["Ton ami,"],"signature":"Anirudh"},"en":{"date":"Delhi, 21 January 2022","salutation":"Dear Denis,","paras":["Thank you for your letter in which you explained the political system of France to me. I am going to describe the political system in India to you.","Like in France, parliament is made up of two chambers: the Lok Sabha and the Rajya Sabha. The people elect the members of the Lok Sabha.","The leader of the political party that wins a majority of votes becomes the Prime Minister, and he in turn chooses the other ministers. In India, it is the Prime Minister who is the head of government.","Presidential elections are different in India. The President is elected by the members of parliament and of the state legislative assemblies.","And in your country, who has the most power?"],"closing":["Your friend,"],"signature":"Anirudh"}},"vocab":[["deux chambres : la Lok Sabha et la Rajya Sabha","two chambers"],["le peuple élit les membres de la Lok Sabha","the people elect the Lok Sabha members"],["gagner une majorité des voix","to win a majority of votes"],["il choisit les autres ministres","he chooses the other ministers"],["le chef du gouvernement","the head of government"],["l'assemblée législative des états","the state legislative assembly"]],"bank":[["Comme en France, le parlement se compose de deux chambres.","Like France, parliament is made up of two chambers."],["Le peuple élit les membres de la Lok Sabha.","The people elect the members of the Lok Sabha."],["Le chef du parti qui gagne une majorité des voix devient le Premier ministre.","The leader of the party that wins a majority becomes Prime Minister."],["Lui à son tour choisit les autres ministres.","He in turn chooses the other ministers."],["Le président est élu par les membres du parlement.","The President is elected by the members of parliament."]],"notes":["Correction : « deux maisons » → « deux chambres » (au parlement, house se traduit par chambre) ; « le Lok Sabha » → « la Lok Sabha » ; virgule ajoutée après l'appel.","Ajout : la question finale « Et chez toi, qui a le plus de pouvoir ? » n'est pas dans la lettre d'origine.","Astuce de structure : « Comme en France… » organise toute la comparaison et montre que vous connaissez les deux systèmes."]}]},{"group":"Exam Practice","topics":[{"id":"prac-sujets","kind":"lesson","fr":{"title":"Tous les sujets possibles","paras":["Le jour de l'examen, on vous donne trois sujets et vous en choisissez un seul. Voici tout ce que le jury a demandé depuis 2017, avec le nombre de fois.","La santé (un ami malade) est arrivée quatre fois : en 2019, 2022, 2024 et 2025. C'est de loin le sujet le plus fréquent. Le système politique français est venu trois fois : en 2017, 2019 et 2025.","Ensuite, quatre sujets sont tombés deux fois chacun : la bibliothèque ou un livre, le système scolaire, les loisirs, et le travail. Les médias et l'environnement ne sont pas tombés dans ces six copies, mais ils restent au programme.","Apprenez à fond les quatre premiers et la probabilité de voir un sujet préparé devient très élevée."]},"en":{"title":"Every Possible Topic","paras":["On exam day you are given three topics and you choose only one. Here is everything the board has asked since 2017, with how often.","Health (a sick friend) has come up four times: in 2019, 2022, 2024 and 2025. That is by far the most frequent topic. The French political system has come up three times: in 2017, 2019 and 2025.","After that, four topics have appeared twice each: the library or a book, the school system, hobbies, and work. Media and the environment did not appear in these six papers, but they are still on the syllabus.","Learn the top four thoroughly and the chance of seeing a topic you have prepared becomes very high."]},"box":{"tone":"tip","fr":"Quatre sujets bien préparés valent mieux que dix sujets survolés. Vous n'en écrirez qu'un seul.","en":"Four well-prepared topics beat ten half-remembered ones. You will only ever write one."}},{"id":"prac-choisir","kind":"lesson","fr":{"title":"Choisir en trente secondes","paras":["Lisez les trois sujets avant d'écrire quoi que ce soit. Trente secondes bien employées vous évitent de vous bloquer au milieu de la copie.","Première question : de quel sujet est-ce que je connais déjà huit phrases ? Choisissez celui-là, pas celui qui a l'air le plus intéressant.","Deuxième question : à qui est-ce que j'écris ? Un ami, un cousin, une mère, un correspondant ? Cela fixe l'appel et la signature avant même de commencer.","Troisième question : est-ce que je donne un conseil ou est-ce que je décris ? Un conseil demande l'impératif et « il faut que ». Une description demande le présent et une question à la fin."]},"en":{"title":"Choosing in Thirty Seconds","paras":["Read all three topics before you write anything. Thirty seconds spent well stops you getting stuck halfway through.","First question: which topic do I already know eight sentences for? Choose that one, not the one that sounds most interesting.","Second question: who am I writing to? A friend, a cousin, a mother, a pen-friend? That fixes your greeting and your signature before you even start.","Third question: am I giving advice, or describing something? Advice needs the imperative and \"il faut que\". A description needs the present tense and a question at the end."]},"box":{"tone":"rule","fr":"Écrivez ensuite le squelette — date, appel, signature — avant la moindre phrase de contenu. Si le temps manque, les points de format sont déjà acquis.","en":"Then write the skeleton — date, greeting, signature — before a single sentence of content. If you run out of time, the format marks are already banked."}},{"id":"prac-checklist","kind":"lesson","fr":{"title":"La check-list finale","paras":["Gardez deux minutes à la fin. Cette relecture vaut plusieurs points et ne demande aucune inspiration.","La faute la plus fréquente n’arrive pas au début : on commence en « tu », on glisse vers « vous » au deuxième paragraphe, et on ne le remarque jamais."]},"en":{"title":"The Final Checklist","paras":["Keep two minutes at the end. This re-read is worth several marks and requires no inspiration at all.","The commonest mistake does not happen at the start: you begin with \"tu\", drift into \"vous\" in the second paragraph, and never notice."]},"box":{"tone":"warn","fr":"Barème indicatif sur 10 : format 2 · registre « tu » 2 · contenu pertinent 3 · variété et correction grammaticales 3.","en":"Rough mark scheme out of 10: format 2 · using \"tu\" 2 · relevant content 3 · grammar range and accuracy 3."},"visual":"checklist"}]}];
